"""Before/after journal for D4.1; never edits historical D4 evidence."""
import difflib,hashlib,json
from pathlib import Path
P=Path(__file__).resolve().parents[1];W=P.parent;ROOT=W.parents[2];H=P/'d4-1'
read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
m=read(P/'history/plan-manifest-d4.json');arc=P/'history/d4-candidate';changes=[];patch=[]
for rel,oldhash in m['files'].items():
 if '/planning/history/'in rel:continue
 p=ROOT/rel
 if sha(p)==oldhash:continue
 old=(arc/rel).read_text();new=p.read_text();a=old.splitlines();b=new.splitlines();spans=[]
 for tag,i,j,k,l in difflib.SequenceMatcher(None,a,b,autojunk=False).get_opcodes():
  if tag!='equal':spans.append(dict(before_line=i+1,after_line=k+1,before='\n'.join(a[i:j]),after='\n'.join(b[k:l])))
 diff='\n'.join(difflib.unified_diff(a,b,fromfile='D4/'+rel,tofile='D4.1/'+rel,lineterm=''))+'\n'
 changes.append(dict(path=rel,before_sha256=oldhash,after_sha256=sha(p),spans=spans,diff=diff));patch.append(diff)
evidence=dict(baseline_manifest_sha256=sha(P/'history/plan-manifest-d4.json'),changed_preexisting_files=len(changes),changes=changes,scope='Every changed pre-existing D4 candidate path outside immutable history; new errata validation/report/recovery files are listed by the final plan manifest. Old archives/reviews/sources are verified separately by freeze-plan.')
(H/'changes.json').write_text(json.dumps(evidence,indent=2,ensure_ascii=False)+'\n');(H/'D4-to-D4.1.diff').write_text('\n'.join(patch))
